/* --------------------------------
共通
-------------------------------- */
div.h2_wrapper {
	display: table;
	width: 100%;
	min-height: 50px;
	padding-left: 56px;
	padding-bottom: 5px;
	border-bottom: 3px solid #efefef;
	margin-bottom: 15px;
	line-height: 28px;
}
div.h2_wrapper > p {
	display: table-cell;
	font-size: 26px;
	font-weight: bold;
	vertical-align: bottom;
	text-shadow: 1px 1px 2px rgba(0,0,0,0.25);
}
div.h3_wrapper {
	display: table;
	width: 100%;
	min-height: 34px;
	padding-left: 42px;
	padding-bottom: 5px;
	border-bottom: 2px solid #efefef;
	margin: 15px 0 15px 32px;
	line-height: 23px;
}
div.h3_wrapper > p {
	display: table-cell;
	font-size: 21px;
	font-weight: bold;
	vertical-align: bottom;
	text-shadow: 1px 1px 2px rgba(0,0,0,0.25);
}
div#bottom_banner {
	 width:100%;
	 text-align: center;
}
div#bottom_banner img {
	box-shadow: 0 0 15px 1px rgba(0,0,0,0.1);
	margin: 10px;
}
p.indent {
	text-indent: 1rem;
}
p.style1 {
	font-size: 0.9rem;
	margin-bottom: 1rem;
}
p.style2 {
	font-size: 1.2rem;
	font-weight: bold;
	margin-bottom: 1rem;
	padding-left: 5px;
	border-left: 5px solid darkgreen;
}
p.style3 {
	font-size: 1rem;
	font-weight: bold;
	margin-top: 1rem;
	margin-bottom: 1rem;
	padding-left: 5px;
	border-left: 5px solid orange;
	border-right: 5px solid orange;
}
p.style4 {
	font-size: 0.8rem;
	font-weight: bold;
	margin-bottom: 1rem;
	padding-left: 5px;
	border-left: 5px solid green;
}
hr.style1 {
	border: 2px solid #efefef;
	margin-bottom: 1rem;
}
h3.style1 {
	font-size: 1.3rem;
	text-shadow: 1px 1px 2px rgba(0,0,0,0.5);
	line-height: 1.5rem;
	padding: 0 0 3px 3px;
	margin-bottom: 1rem;
	border-bottom: 5px solid #efefef;
}
h4.style1 {
	margin-top: 1rem;
	margin-bottom: 0.5rem;
	font-size: 1.1rem;
	text-shadow: 1px 1px 2px rgba(0,0,0,0.5);
}
ul.style1,
ol.style1 {
	font-size: 0.9rem;
	line-height: 1.5rem;
	margin-top: 1rem;
	margin-bottom: 1rem;

  background: #efefef;
  border-radius: 8px;
  box-shadow: 0px 0px 5px rgba(0,0,0,0.2);
  padding: 1em 1em 1em 2.5em;
}
ul.style1 a,
ol.style1 a {
	text-decoration: underline;
}
ul.style1 > li,
ol.style1 > li ul li {
	position: relative;
	padding-left: 0.4em;
}
ul.style1 > li:before {
	color: darkgreen;
	font-family: FontAwesome;
	content: '\f138';
	font-size: 1.2em;
	position: absolute;
	left: -1em;
	top: 0;
}
ul.style1 > li ul,
ul.style1 > li ol,
ol.style1 > li ul,
ol.style1 > li ol {
	line-height: 1.2rem;
}
ul.style1 > li ul li,
ul.style1 > li ol li,
ol.style1 > li ul li,
ol.style1 > li ol li {
	margin-left: -1rem;
} 
ol.style1 > li ul {
	list-style: none;
}
ol.style1 > li ul li:before {
	color: darkgreen;
	font-family: FontAwesome;
	content: '\f0da';
	position: absolute;
	left: -1em;
	top: 0;
}
.lm32 {
	margin-left: 32px;
}
.hm32 {
	margin-left: 32px;
	margin-right: 32px;
}
.red {
	color: red;
}
.blue {
	color: blue;
}
.center {
	text-align: center;
}

/* --------------------------------
サイド
-------------------------------- */
aside {
	width: 100%;
}
aside a {
}
aside a img {
	vertical-align: bottom;
}

/* --------------------------------
トップページ
-------------------------------- */
p.yoyaku_button a {
	display: block;
	width: 90%;
	margin: 2rem auto 0;
	border-radius: 5px;
	background: rgba(0,0,255,0.5);
	color: #fff;
	padding: 30px;
	text-align: center;
	font-size: 2rem;
	font-weight: bold;
	-webkit-transition: all 0.3s ease;
	-moz-transition: all 0.3s ease;
	transition: all 0.3s ease;
}
p.yoyaku_button a:hover {
	background: rgba(0,0,255,0.8);
}

/* --------------------------------
予約入力フォーム
-------------------------------- */
h3.style2 {
	border-top: 1px solid red;
	border-bottom: 1px solid red;
	border-left: 20px solid red;
	border-right: 1px solid red;
	border-radius: 0 8px 8px 0;
	padding: 1rem;
	font-size: 1.4rem;
	color: red;
	margin: 0 0 1rem 0;
	text-shadow: 1px 1px 2px rgba(255,0,0,0.5);
}
p.rentalboat2020_date {
	text-align: right;
	margin: 2rem 0;
	padding: 0.5rem 1rem 0 0;
	border-top: 5px solid #efefef;
	font-size: 1rem;
}

/* --------------------------------
ポリシー
-------------------------------- */
table.style1 {
  font-size: 0.8rem;
  border-collapse: separate;
  border-spacing: 3px;
  width: 80%;
  margin: 0 auto 2rem;
  box-sizing: border-box;
  border-radius: 5px;
}
table.style1 th,
table.style1 td {
  border: 1px solid #efefef;
  padding: 3px 5px;
  border-radius: 3px;
}
table.style1 th {
  text-align: left;
  background: #efefef;
  vertical-align: top;
  min-width: 110px;
  max-width: 110px;
}
div#legal_signature {
	width: 100%;
	float: none;
}
div#legal_signature p {
	display: block;
	float: right;
}

